package native

import (
	"encoding/json"
	"os"
	"os/exec"
	"reflect"
	"sort"
	"testing"

	"github.com/angeles725/sdd-investigacion/research-sdd/rsdd/internal/testkit/kitroot"
)

// legacyFixtures are reports the Python driver produced from a real radare2 run (regenerated by
// tests/regen-lane-fixtures.sh); they pin the shape consumers read.
var legacyFixtures = kitroot.Must() + "/toolbelt/tests/fixtures/lane/corroborate-native-r2/"

// shape lists every key path of a JSON document (arrays contribute their first element's shape), except under
// the keys in skip, whose subtree is opaque.
func shape(prefix string, v any, skip map[string]bool, out *[]string) {
	switch x := v.(type) {
	case map[string]any:
		for k, child := range x {
			p := prefix + "/" + k
			*out = append(*out, p)
			if !skip[k] {
				shape(p, child, skip, out)
			}
		}
	case []any:
		if len(x) > 0 {
			shape(prefix+"[]", x[0], skip, out)
		}
	}
}

func shapeOf(t *testing.T, raw []byte) []string {
	t.Helper()
	var v any
	if err := json.Unmarshal(raw, &v); err != nil {
		t.Fatal(err)
	}
	var s []string
	shape("", v, map[string]bool{"functions": true}, &s)
	sort.Strings(s)
	return s
}

// The report keeps every key the Python report had. `runtime.python` is the one declared rename (see doc.go).
func TestReportKeepsTheLegacyShape(t *testing.T) {
	legacy, err := os.ReadFile(legacyFixtures + "happy.json")
	if err != nil {
		t.Fatal(err)
	}
	w := newWorld(t)
	if rc := w.run("shape"); rc != 0 {
		t.Fatalf("rc=%d %q", rc, w.errBuf.String())
	}
	got, err := os.ReadFile(w.path("shape/native-static.v1.json"))
	if err != nil {
		t.Fatal(err)
	}
	want := shapeOf(t, legacy)
	for i, p := range want {
		if p == "/runtime/python" {
			want[i] = "/runtime/go"
		}
	}
	sort.Strings(want)
	if have := shapeOf(t, got); !reflect.DeepEqual(have, want) {
		t.Fatalf("key paths differ:\n got %v\nwant %v", have, want)
	}
}

// A real radare2 under a real Bubblewrap, as the slow lane of the legacy suite did. It needs both tools and
// namespace support, so it skips (loudly) where they are absent.
func TestRealRadare2UnderBubblewrap(t *testing.T) {
	for _, tool := range []string{"r2", "bwrap"} {
		if _, err := exec.LookPath(tool); err != nil {
			t.Skipf("%s not installed: the real-tool check is skipped, the fake-tool suite above still ran", tool)
		}
	}
	if err := exec.Command("bwrap", "--unshare-net", "--ro-bind", "/", "/", "/bin/true").Run(); err != nil {
		t.Skipf("bubblewrap cannot create namespaces here: %v", err)
	}
	w := newWorld(t)
	w.d = realDeps()
	w.env = map[string]string{"PATH": os.Getenv("PATH")}
	bin, err := exec.LookPath("true")
	if err != nil {
		t.Skip(err)
	}
	w.input = bin
	if rc := w.run("real"); rc != 0 {
		t.Fatalf("rc=%d stderr=%q", rc, w.errBuf.String())
	}
	rep := w.readJSON("real/native-static.v1.json")
	if rep["status"] != "complete" || sub(rep, "counts", "functions_emitted").(float64) < 1 {
		t.Fatalf("status %v counts %v errors %v", rep["status"], rep["counts"], rep["errors"])
	}
	w.verify(w.path("real"))
}
